program='''from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    for comp in components:
        r0 = min(r for r, _ in comp)
        r1 = max(r for r, _ in comp)
        c0 = min(c for _, c in comp)
        c1 = max(c for _, c in comp)
        top_cols = [c for r, c in comp if r == r0]
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if out[r][c] == 0:
                    out[r][c] = 2
        gaps = [c for c in range(min(top_cols), max(top_cols) + 1) if grid[r0][c] == 0]
        if gaps and r0 > 0:
            gap = gaps[0]
            left_count = sum(grid[r0][c] == 5 for c in range(c0, gap))
            right_count = sum(grid[r0][c] == 5 for c in range(gap + 1, c1 + 1))
            if left_count >= right_count:
                for c in range(gap + 1):
                    out[r0 - 1][c] = 2
            else:
                for c in range(gap, w):
                    out[r0 - 1][c] = 2
    return out
'''
